package org.jlinalg.cli;

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.assembly.HifiasmGfa;
import org.jlinalg.assembly.HifiasmYak;
import org.jlinalg.assembly.HifiasmReads;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/**
 * Exact-source upstream hifiasm assembly with native complete input/GFA/FASTA
 * admission. All cases remain provisional until the single final receipt passes.
 * This adapter never substitutes a Java consensus/phasing algorithm for hifiasm.
 */
public final class HifiasmWorkflowCli {
    private HifiasmWorkflowCli(){ }
    public static void main(String[] args){System.exit(run(args));}
    public static int run(String[] args){
        Path out=null;int exit=2;var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_HIFIASM_WORKFLOW");state.put("analysis_admitted",false);state.put("started_at",Instant.now().toString());var completed=new ArrayList<Object>();var warnings=new ArrayList<String>();
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request explicit-hifiasm-workflow.json");var request=HifiasmWorkflowRequest.read(Path.of(args[1]));out=Files.createDirectory(request.out());Files.write(out.resolve("request.original.json"),NextflowFiles.bytes(request.source(),16777216),StandardOpenOption.CREATE_NEW);warnings(out,state,warnings);NextflowFiles.writeJson(out.resolve("effective-limits.json"),HifiasmJson.value(request.limits()));HifiasmWorkflowRequest.available(request);HifiasmHost.platform();
            var runtime=HifiasmRuntime.prepare(request.runtime(),request.edition(),out.resolve("host-before"));Files.write(out.resolve("runtime.original.json"),NextflowFiles.bytes(runtime.manifest(),33554432),StandardOpenOption.CREATE_NEW);var pins=new LinkedHashMap<Path,NextflowFiles.Pin>();pins.put(request.source(),NextflowFiles.pin(request.source(),16777216,()->{}));pins.put(out.resolve("request.original.json"),pins.get(request.source()));pins.put(out.resolve("runtime.original.json"),runtime.manifestPin());Path captured=Files.createDirectory(out.resolve("inputs"));var paths=new LinkedHashMap<String,Path>();var inspections=new LinkedHashMap<String,HifiasmReads.Inspection>();var parentTables=new LinkedHashMap<String,HifiasmYak.Inspection>();
            for(var input:request.inputs()){
                cancelled(request.out());budget(request.out(),request.limits().process());
                Path original=HifiasmRuntime.regular(input.path(),request.limits().reads().encodedBytes());for(Path previous:paths.values())require(!Files.isSameFile(original,previous),"Input aliases are not allowed");require(input.pin().equals(NextflowFiles.pin(original,request.limits().reads().encodedBytes(),()->{})),"Original input differs from its declared complete pin: "+input.id());for(var other:request.inputs())if(!other.id().equals(input.id()))require(!Files.isSameFile(original,other.path()),"Two input identifiers resolve to the same original file");Path copy=captured.resolve(input.id()+(input.kind().equals("yak")?".yak":".reads"));Files.copy(original,copy);require(input.pin().equals(NextflowFiles.pin(copy,request.limits().reads().encodedBytes(),()->{})),"Captured input differs");paths.put(input.id(),copy);pins.put(original,input.pin());pins.put(copy,input.pin());
                if(input.kind().equals("reads")){var inspection=HifiasmReads.inspect(Files.newInputStream(copy),request.limits().reads(),false);inspections.put(input.id(),inspection);NextflowFiles.writeJson(captured.resolve(input.id()+".inspection.json"),HifiasmJson.value(inspection));}
                else try(var stream=new BufferedInputStream(Files.newInputStream(copy),65536)){var table=HifiasmYak.inspect(stream,new HifiasmYak.Limits(request.limits().reads().encodedBytes(),request.limits().reads().encodedBytes()/8,request.limits().parentEntriesPerBucket()));parentTables.put(input.id(),table);NextflowFiles.writeJson(captured.resolve(input.id()+".inspection.json"),Map.of("stored_count_summary",HifiasmJson.value(table),"count_provenance_encoded_in_file",false,"yak_runtime_used_by_this_adapter",false,"inspection_memory_scope","One bucket of hash words; full entry population scanned without materializing the complete database"));}
            }
            // Preflight EVERY requested analysis before launching the first assembly.
            for(var analysis:request.analyses()){
                var ids=new HashSet<String>();for(String name:join(analysis.reads(),analysis.ultralong()))for(String id:inspections.get(name).reads().keySet())require(ids.add(id),"Repeated original main/UL read identity across files in "+analysis.id()+": "+id);
                if(analysis.mode().equals("ont"))for(String name:analysis.reads())require(inspections.get(name).format().equals("FASTQ"),"ONT-only requires real FASTQ qualities for every input record; FASTA is rejected before upstream's zero-exit error");
                for(var pair:analysis.hic()){var paired=HifiasmReads.inspectPair(Files.newInputStream(paths.get(pair.first())),Files.newInputStream(paths.get(pair.second())),request.limits().reads(),false);NextflowFiles.writeJson(captured.resolve(analysis.id()+"-"+pair.first()+"-"+pair.second()+".pairs.json"),HifiasmJson.value(paired.pairs()));}
                if(analysis.paternal()!=null){var first=parentTables.get(analysis.paternal());var second=parentTables.get(analysis.maternal());require(first.k()==second.k()&&first.prefixBits()==second.prefixBits(),"Parental YAK k/prefix populations disagree");}
            }
            budget(request.out(),request.limits().process());long pinnedCapacity=Math.max(Math.max(33554432,request.limits().reads().encodedBytes()),request.limits().process().fileBytes());var populations=new LinkedHashMap<Path,java.util.Set<Path>>();populations.put(captured,population(captured));populations.put(out.resolve("host-before"),population(out.resolve("host-before")));freeze(out,pins,pinnedCapacity);RsemProcess.Check check=()->{cancelled(request.out());runtime.verify();for(var entry:pins.entrySet())require(entry.getValue().equals(NextflowFiles.pin(entry.getKey(),pinnedCapacity,()->{})),"Previously bound input, metadata, original output or native result changed during assembly: "+entry.getKey());for(var entry:populations.entrySet())require(entry.getValue().equals(population(entry.getKey())),"Previously completed evidence population changed: "+entry.getKey());};check.verify();HifiasmVersionProbe.probe(runtime.build().binary(),request.edition(),HifiasmHost.environment(),out.resolve("version"),check);freeze(out.resolve("version"),pins,pinnedCapacity);populations.put(out.resolve("version"),population(out.resolve("version")));
            Path cases=Files.createDirectory(out.resolve("analyses"));
            for(var analysis:request.analyses()){
                Path home=Files.createDirectory(cases.resolve(analysis.id())),assembly=Files.createDirectory(home.resolve("original")),exports=Files.createDirectory(home.resolve("native"));var command=new ArrayList<String>(List.of(runtime.build().binary().toString(),"-o",assembly.resolve("asm").toString(),"-t",Integer.toString(analysis.threads()),"-f",Integer.toString(analysis.bloomBits()),"-i"));
                if(analysis.paternal()!=null)command.addAll(List.of("-1",paths.get(analysis.paternal()).toString(),"-2",paths.get(analysis.maternal()).toString()));if(!analysis.hic().isEmpty()){var first=new ArrayList<String>();var second=new ArrayList<String>();for(var pair:analysis.hic()){first.add(paths.get(pair.first()).toString());second.add(paths.get(pair.second()).toString());}command.addAll(List.of("--h1",String.join(",",first),"--h2",String.join(",",second)));}if(!analysis.ultralong().isEmpty())command.addAll(List.of("--ul",paths.get(analysis.ultralong().get(0)).toString()));if(analysis.mode().equals("ont"))command.add("--ont");if(analysis.purgeLevel()!=null)command.addAll(List.of("-l",analysis.purgeLevel().toString()));if(analysis.disablePostJoin())command.add("-u");for(String name:analysis.reads())command.add(paths.get(name).toString());
                NextflowFiles.writeJson(home.resolve("command.json"),command);System.out.println("hifiasm "+request.edition()+" "+analysis.id()+" (provisional)");Runnable cancellation=()->{try{cancelled(request.out());budget(request.out(),request.limits().process());}catch(IOException failed){throw new java.io.UncheckedIOException(failed);}};var result=RsemProcess.executeOwned(command,HifiasmHost.environment(),home.resolve("process"),request.limits().process(),check,cancellation,List.of(assembly,captured));require(result.exitCode()==0&&result.ownedLiveAfterCleanup().isEmpty(),"Original assembly or owned cleanup failed");String diagnostic=NextflowFiles.utf8(NextflowFiles.bytes(result.stderr(),16777216));require(!diagnostic.contains("[ERROR]")&&!diagnostic.contains("[E::"),"Original assembly reports an error despite exit0; read complete retained original stderr");
                var graphReports=new ArrayList<Object>();var originalFiles=new LinkedHashMap<String,Object>();var normalized=new LinkedHashMap<String,String>();var readIds=new HashSet<String>();for(String name:join(analysis.reads(),analysis.ultralong()))readIds.addAll(inspections.get(name).reads().keySet());long sequenceBases=0;int graphCount=0;
                try(var tree=Files.walk(assembly)){
                    for(Path file:tree.sorted().toList()){
                        require(!Files.isSymbolicLink(file),"Original output contains a symbolic link");if(Files.isDirectory(file,LinkOption.NOFOLLOW_LINKS))continue;require(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS),"Original output contains a nonregular node");String name=assembly.relativize(file).toString();var originalPin=NextflowFiles.pin(file,request.limits().process().fileBytes(),()->{});pins.put(file,originalPin);originalFiles.put(name,GseapyExecutionRuntime.pinObject(originalPin));if(!name.endsWith(".gfa"))continue;graphCount++;
                        HifiasmGfa.Graph graph;try(var input=new BufferedInputStream(Files.newInputStream(file),65536)){graph=HifiasmGfa.read(input,request.limits().graph());}var statistics=graph.statistics();long matched=0,virtual=0;for(var placement:graph.placements())if(!placement.gap()){if(readIds.contains(placement.read()))matched++;else if(placement.read().equals("FAKE")&&placement.tags().stream().anyMatch(t->t.name().equals("HG")&&t.value().equals("*")))virtual++;else throw new IOException("Original GFA placement has no captured main/UL read identity: "+placement.read());}
                        if(name.endsWith(".noseq.gfa")){String companion=name.substring(0,name.length()-10)+".gfa";require(normalized.containsKey(companion)&&normalized.get(companion).equals(digest(graph,false)),"Original no-sequence graph differs from its complete sequence-bearing companion");}else normalized.put(name,digest(graph,true));
                        HifiasmGfa.FastaReport fasta;if(statistics.sequenceBearingSegments()>0){Path target=exports.resolve(name+".fasta");MessageDigest expectedFasta=MessageDigest.getInstance("SHA-256");try(var stream=new java.security.DigestOutputStream(new BufferedOutputStream(Files.newOutputStream(target,StandardOpenOption.CREATE_NEW),65536),expectedFasta)){fasta=HifiasmGfa.writeFasta(graph,stream,80,true);}var fastaPin=NextflowFiles.pin(target,request.limits().process().fileBytes(),()->{});require(fastaPin.sha256().equals(HexFormat.of().formatHex(expectedFasta.digest())),"Complete native FASTA bytes changed while writing/capturing");pins.put(target,fastaPin);sequenceBases=Math.addExact(sequenceBases,fasta.sequenceBases());}else fasta=new HifiasmGfa.FastaReport(List.of(),new ArrayList<>(graph.segments().keySet()),0);
                        var report=new LinkedHashMap<String,Object>();report.put("graph",name);report.put("statistics",HifiasmJson.value(statistics));report.put("diagnostics",graph.diagnostics());report.put("fasta",HifiasmJson.value(fasta));report.put("fasta_file",statistics.sequenceBearingSegments()>0?name+".fasta":null);report.put("source_placements_matched_input_identity",matched);report.put("source_virtual_placements",virtual);report.put("corrected_read_coordinates_recomputed",false);graphReports.add(report);if(!graph.diagnostics().isEmpty()||!fasta.omitted().isEmpty())warnings.add(analysis.id()+"/"+name+": retained source diagnostics or omitted sequences; read its complete graph report");
                    }
                }
                require(graphCount>0&&sequenceBases>0,"Original exit0 produced no nonempty sequence-bearing GFA family; no result admitted");check.verify();NextflowFiles.writeJson(home.resolve("original-files.json"),originalFiles);NextflowFiles.writeJson(home.resolve("graph-audit.json"),graphReports);var report=Map.<String,Object>of("id",analysis.id(),"mode",analysis.mode(),"original_exit_code",result.exitCode(),"graph_views",graphCount,"sequence_bases_across_graph_views",sequenceBases,"source_namespace_patched",false,"analysis_admitted",false,"status","PROVISIONAL_ORIGINAL_ASSEMBLY_AND_NATIVE_GRAPH_AUDIT_ONLY");NextflowFiles.writeJson(home.resolve("PROVISIONAL.json"),report);completed.add(report);freeze(home,pins,pinnedCapacity);populations.put(home,population(home));check.verify();budget(request.out(),request.limits().process());
            }
            check.verify();var after=HifiasmHost.capture(runtime.build().binary(),out.resolve("host-after"),()->{cancelled(request.out());runtime.build().verifyRuntime();});require(runtime.host().equals(after),"Original host/library/search bindings changed across assembly batch");check.verify();freeze(out,pins,pinnedCapacity);var files=inventory(out,request.limits().process());NextflowFiles.writeJson(out.resolve("result-files.json"),files);state.put("result_files_pin",GseapyExecutionRuntime.pinObject(NextflowFiles.pin(out.resolve("result-files.json"),33554432,()->{})));check.verify();budget(out,request.limits().process());state.put("status","PASS_COMPLETE_ORIGINAL_HIFIASM_AND_NATIVE_GRAPH_WORKFLOW");state.put("analysis_admitted",true);state.put("edition",request.edition());state.put("commit",runtime.build().commit());state.put("analyses",completed);state.put("source_namespace_patched",false);state.put("analysis_installed_software",false);state.put("raw_inputs_unchanged",true);state.put("host_bindings_unchanged",true);state.put("structural_graph_validation_only",true);state.put("biological_or_paper_reproduction_certified",false);state.put("owned_live_after_cleanup",List.of());exit=0;
        }catch(RsemProcess.UnavailableDependency unavailable){state.put("status","SKIP3_HIFIASM_DEPENDENCY_OR_MODE_UNAVAILABLE");details(state,out,unavailable);exit=3;System.err.println(state.get("status")+": "+unavailable+"\n"+HifiasmRuntime.ACTION);}
        catch(Exception failed){state.put("analysis_admitted",false);details(state,out,failed);System.err.println(state.get("status")+": "+failed+"\n"+HifiasmRuntime.ACTION);failed.printStackTrace(System.err);}
        finally{state.put("finished_at",Instant.now().toString());state.put("earlier_cases_are_provisional_unless_entire_receipt_passes",completed);if(out!=null)try{warnings(out,state,warnings);state.put("warnings_pin",GseapyExecutionRuntime.pinObject(NextflowFiles.pin(out.resolve("WARNINGS.md"),16777216,()->{})));NextflowFiles.writeJson(out.resolve("COMPLETED.json"),state);if(exit==0)System.out.println(state.get("status")+": "+out.resolve("COMPLETED.json"));}catch(Exception failure){System.err.println("FAIL2: final admission receipt unavailable; retain this unadmitted directory: "+failure);exit=2;}}
        return exit;
    }
    private static List<String> join(List<String> first,List<String> second){var result=new ArrayList<>(first);result.addAll(second);return result;}
    private static java.util.Set<Path> population(Path scope)throws IOException{var result=new HashSet<Path>();try(var tree=Files.walk(scope)){for(Path path:tree.toList()){require(!Files.isSymbolicLink(path)&&(Files.isDirectory(path,LinkOption.NOFOLLOW_LINKS)||Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)),"Previously completed evidence contains a linked/nonregular node");result.add(path);}}return java.util.Set.copyOf(result);}
    private static void cancelled(Path out)throws IOException{require(!Files.exists(out.resolve("CANCEL_REQUESTED"),LinkOption.NOFOLLOW_LINKS)&&!Thread.currentThread().isInterrupted(),"Cancellation requested; no analysis admitted");}
    private static void details(Map<String,Object> state,Path out,Exception failure){state.put("error",failure.toString());var errors=new ArrayList<String>();var pending=new ArrayList<Throwable>();var seen=java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<Throwable,Boolean>());pending.add(failure);for(int i=0;i<pending.size()&&errors.size()<64;i++){Throwable error=pending.get(i);if(!seen.add(error))continue;errors.add(error.toString());if(error.getCause()!=null)pending.add(error.getCause());pending.addAll(List.of(error.getSuppressed()));}state.put("error_details",errors);if(out!=null)try{var text=new java.io.StringWriter();failure.printStackTrace(new java.io.PrintWriter(text));Files.writeString(out.resolve("error.traceback.txt"),text.toString(),StandardOpenOption.CREATE_NEW);}catch(IOException diagnostic){System.err.println("FAIL2: error detail file unavailable: "+diagnostic);}}
    private static void freeze(Path scope,Map<Path,NextflowFiles.Pin> pins,long capacity)throws IOException{try(var tree=Files.walk(scope)){for(Path file:tree.toList()){require(!Files.isSymbolicLink(file),"Owned evidence contains a symbolic link");if(Files.isDirectory(file,LinkOption.NOFOLLOW_LINKS))continue;require(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS),"Owned evidence contains a nonregular node");var actual=NextflowFiles.pin(file,capacity,()->{});var before=pins.putIfAbsent(file,actual);require(before==null||before.equals(actual),"Previously completed evidence changed before batch admission: "+file);}}}
    private static String digest(HifiasmGfa.Graph graph,boolean omitSequence)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");for(String line:graph.sourceLines()){if(omitSequence&&line.startsWith("S\t")){String[] f=line.split("\t",-1);f[2]="*";line=String.join("\t",f);}digest.update(line.getBytes(StandardCharsets.UTF_8));digest.update((byte)'\n');}return HexFormat.of().formatHex(digest.digest());}
    private static Map<String,Object> inventory(Path out,RsemProcess.Limits limits)throws IOException{var result=new LinkedHashMap<String,Object>();try(var tree=Files.walk(out)){for(Path file:tree.sorted().toList()){require(!Files.isSymbolicLink(file),"Owned output contains a symbolic link");if(Files.isDirectory(file,LinkOption.NOFOLLOW_LINKS))continue;require(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS),"Owned output contains a nonregular node");if(!file.equals(out.resolve("WARNINGS.md")))result.put(out.relativize(file).toString().replace('\\','/'),GseapyExecutionRuntime.pinObject(NextflowFiles.pin(file,Math.max(limits.fileBytes(),33554432),()->{})));}}return result;}
    private static void budget(Path out,RsemProcess.Limits limits)throws IOException{long bytes=0;int count=0;try(var tree=Files.walk(out)){for(Path file:tree.toList()){require(!Files.isSymbolicLink(file),"Owned output contains a symbolic link");if(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)){bytes=Math.addExact(bytes,Files.size(file));require(++count<=limits.fileCount()&&bytes<=limits.workspaceBytes(),"Complete owned workflow output exceeds declared file/byte capacities");}}}}
    private static void warnings(Path out,Map<String,Object> state,List<String> warnings)throws IOException{StringBuilder message=new StringBuilder("# "+state.get("status")+"\n\n"+HifiasmRuntime.ACTION+"\n\nOnly a complete PASS receipt admits this whole batch. All per-case PROVISIONAL receipts remain subordinate to it. Original error correction, overlap construction, assembly and phasing run upstream. Native GFA statistics and FASTA extraction check the complete declared structural output; they do not independently validate consensus or phase. A coordinates refer to source-corrected reads; raw-length bounds are not inferred. Default HiFi outputs may be partially phased. Graph views overlap and their sequence totals must not be added as genome sizes. Empty haplotype/no-sequence views and all source diagnostics are retained. No-sequence graphs produce an explicit omission ledger, never fabricated bases.\n\nThe bounded-v1 limits are printed in effective-limits.json. Larger inputs require explicit capacities, sufficient Java heap and original-process resources. Sampled RSS is observational, not a hard aggregate RSS bound. Every run uses a NEW prefix and -i; no cached scientific state is reused. Bloom bits, thread count and optional purge/post-join settings are explicit in each command; bounded -f0 controls are not paper-default reproduction.\n\n");if(state.containsKey("error")){message.append("**ACTION REQUIRED: ").append(state.get("error")).append("**\n\n");message.append("Named cause details (also retained in error.traceback.txt):\n\n");for(Object detail:(List<?>)state.get("error_details"))message.append("- ").append(detail).append('\n');message.append('\n');}for(String warning:warnings)message.append("- ").append(warning).append('\n');Files.writeString(out.resolve("WARNINGS.md"),message);}
}
